public class ChannelSwapperTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String colorAt(java.awt.image.BufferedImage img, int x, int y) {
        if (img == null) {
            return "(null image)";
        }
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static int bucket(int[] counts, int index) {
        if (counts == null || index >= counts.length) {
            return -1;
        }
        return counts[index];
    }

    static int length(int[] counts) {
        if (counts == null) {
            return -1;
        }
        return counts.length;
    }

    static java.awt.image.BufferedImage makeSource() {
        java.awt.image.BufferedImage src =
                new java.awt.image.BufferedImage(2, 2, java.awt.image.BufferedImage.TYPE_INT_RGB);
        src.setRGB(0, 0, 0xC8640A);
        src.setRGB(1, 0, 0xC80000);
        src.setRGB(0, 1, 0x0A14FF);
        src.setRGB(1, 1, 0xFFFFFF);
        return src;
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage src = makeSource();

            java.awt.image.BufferedImage swapped = ChannelSwapper.swapRedBlue(src);
            check("swap of (200,100,10) is (10,100,200)", "#0A64C8", colorAt(swapped, 0, 0));
            check("swap keeps green in place", "#0000C8", colorAt(swapped, 1, 0));
            check("swap of (10,20,255) is (255,20,10)", "#FF140A", colorAt(swapped, 0, 1));
            check("swap of white is white", "#FFFFFF", colorAt(swapped, 1, 1));
            check("swapRedBlue returns a new image", true, swapped != null && swapped != src);
            check("src unchanged after swap", "#C8640A", colorAt(src, 0, 0));

            int[] hist = ChannelSwapper.channelHistogramRed(src);
            check("histogram has 256 buckets", 256, length(hist));
            check("two pixels have red 200", 2, bucket(hist, 200));
            check("one pixel has red 10", 1, bucket(hist, 10));
            check("one pixel has red 255", 1, bucket(hist, 255));
            check("no pixel has red 0", 0, bucket(hist, 0));
            check("no pixel has red 100", 0, bucket(hist, 100));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
